function insightCard(x){return `<article class="insight ${x.tone}"><span class="eyebrow">${x.tone==='warning'?'PERLU DITINJAU':'FINANCIAL NOTE'}</span><h3>${esc(x.title)}</h3><p>${esc(x.detail).replace(/\b\d{6,}\b/g,n=>money(+n))}</p><div class="action">↗ ${esc(x.action)}</div><small>${esc(x.confidence)}</small></article>`;}
function insights(){const items=E.insights(c,rows,market,range);$('#content').innerHTML=intro('Angka yang membantu mengambil langkah.','Temuan mengikuti data dan aturan yang terlihat, tanpa mengirim transaksi ke layanan AI.')+`<div class="grid two">${items.map(insightCard).join('')}</div>`+panel('Cara membaca insight','Konteks keluarga tetap menjadi bagian keputusan.',note('Confidence menunjukkan kekuatan dasar data, bukan kepastian hasil masa depan. Kebutuhan persalinan, kesehatan, sekolah dan dukungan keluarga tidak dianggap sebagai “belanja buruk”. Periksa transaksi pembentuk perubahan sebelum mengambil tindakan.'));}
const settingLabels={asOf:'Tanggal posisi',profile:'Profil keluarga',accounts:'Saldo rekening',liabilities:'Kewajiban dan titipan',receivables:'Piutang tunai',prepaids:'Sewa dibayar di muka',deferredRent:'Pendapatan sewa di muka',btcQuantity:'Jumlah BTC',property:'Properti',holdings:'Kepemilikan saham',household:'Rumah tangga',budgets:'Budget bulanan',challenges:'Net Liquidity Challenge',carry:'Cash efficiency',dividends:'Skenario dividen',car:'Asumsi mobil',retirement:'Pensiun April 2050',roadmap:'Milestone keluarga',rules:'Aturan klasifikasi',overrides:'Koreksi transaksi',weekStart:'Awal minggu (1=Senin)',qualityNotes:'Catatan kualitas data',pendingSync:'Referensi sinkronisasi CSV',source:'Sumber posisi',monthlyBudget:'Budget akuntansi / bulan',retirementMonth:'Bulan pensiun',target:'Target utama (Rp)',minimum:'Minimum (Rp)',stretch:'Stretch (Rp)',inflation:'Inflasi tahunan (0,04 = 4%)',feeRate:'Biaya tahunan',returnTaxRate:'Pajak atas return positif',dividendYield:'Yield distribusi pensiun',dividendTaxRate:'Pajak distribusi',reinvestDividends:'Reinvestasikan dividen',todayExpense:'Biaya hidup bulanan hari ini',monthlyWithdrawal:'Penarikan bulanan',drawdownRate:'Penurunan portofolio skenario',contributions:'Setoran bertahap per tahun',amount:'Nominal (Rp)',balance:'Saldo (Rp)'};
function settingInput(value,path){const name=path.split('.').at(-1),label=settingLabels[name]||name.replace(/([A-Z])/g,' $1');if(Array.isArray(value))return `<label class="wide">${esc(label)} · daftar JSON<textarea data-config="${esc(path)}" data-type="json" rows="${Math.min(16,Math.max(4,value.length*2))}" spellcheck="false">${esc(JSON.stringify(value,null,2))}</textarea><small>Edit nilai dalam daftar. Preview perubahan ditampilkan sebelum penyimpanan; sumber transaksi tidak diubah.</small></label>`;if(value&&typeof value==='object')return `<div class="wide"><h3 style="margin:14px 0">${esc(label)}</h3><div class="form-grid">${Object.entries(value).map(([k,v])=>settingInput(v,path+'.'+k)).join('')}</div></div>`;if(typeof value==='boolean')return `<label class="checkbox"><input type="checkbox" data-config="${esc(path)}" data-type="boolean" ${value?'checked':''}>${esc(label)}</label>`;return `<label>${esc(label)}<input data-config="${esc(path)}" data-type="${value===null?'nullable':typeof value}" type="${typeof value==='number'?'number':'text'}" step="any" value="${esc(value??'')}" placeholder="${value===null?'Belum tersedia':''}"></label>`;}
function settings(){const tabs=`<div class="toolbar">${[['health','Data health'],['import','CSV import'],['config','Pengaturan'],['history','Riwayat & rollback']].map(([k,v])=>`<button data-settings="${k}" class="${settingsTab===k?'primary button':''}">${v}</button>`).join('')}</div>`;let body='';
 if(settingsTab==='health'){const recon=E.reconciliation(state.transactions,c),a=E.aggregate(rows),active=state.batches.find(b=>b.id===state.active);body=`<div class="grid four">${metric('Transaksi tersimpan',state.transactions.length.toLocaleString('id-ID'),'Raw CSV dan normalized records tersimpan')}${metric('Belum cocok',E.sum(recon,x=>x.difference),'Total selisih screenshot − ledger','warning')}${metric('Perlu review klasifikasi',String(a.review),'Termasuk penjualan dengan basis belum terverifikasi')}${metric('Snapshot terakhir',fmtDate(c.asOf),'Provisional · menunggu rekonsiliasi')}</div>`+panel('Rekonsiliasi rekening','Tidak ada jurnal penyeimbang otomatis.',table(['Rekening','Ledger','Snapshot','Selisih'],recon.filter(x=>x.recorded||x.confirmed||x.difference).map(x=>`<tr><td>${esc(x.name)}</td>${num(x.recorded)}${num(x.confirmed)}${num(x.difference,x.difference?'warning':'positive')}</tr>`).join('')))+panel('Hal yang perlu ditindaklanjuti',`${active?.filename||''} · import ${new Date(active?.at).toLocaleString('id-ID')}`,c.qualityNotes.map(x=>note(`<strong>${esc(x.title)}</strong><br>${esc(x.detail)}`,'warning')).join('')+note('Harga saham '+esc(valuation?.priceDate||'belum tersedia')+'; BTC '+esc(market.source||'belum tersedia')+'. Snapshot baru tidak mengubah histori transaksi.'))+panel('Snapshot & penutupan bulanan','Penutupan final hanya setelah bulan berakhir, posisi bertanggal akhir bulan, dan seluruh rekening cocok.',btn('Catat snapshot posisi','snapshot')+note('Snapshot provisional boleh dicatat sekarang. Belum ada rekonsiliasi otomatis untuk cash support yang hilang.'));}
 if(settingsTab==='config'){draft=draft||structuredClone(c);body=note('Nilai nominal menggunakan rupiah bulat. Persentase ditulis desimal (0.04 = 4%). Kolom kosong berarti belum diketahui. Daftar rekening/budget memakai editor data terstruktur; tidak mengubah file kode.')+Object.entries(draft).filter(([k])=>!['overrides','pendingSync'].includes(k)).map(([k,v])=>`<details class="config-section" data-section="${k}" ${k==='retirement'?'open':''}><summary>${esc(settingLabels[k]||k)}</summary><div class="form-grid">${settingInput(v,k)}</div></details>`).join('')+`<div class="config-savebar"><span>Perubahan disimpan sebagai versi baru.</span>${btn('Tinjau perubahan','config-preview','primary')}</div>`;}
 if(settingsTab==='import'){body=panel('01 · Pilih ekspor Money Lover','Gunakan seluruh periode; sertakan Exclude Report untuk rekonsiliasi lengkap.',`<div class="dropzone" id="dropzone"><div class="drop-icon">↥</div><strong>Drop CSV di sini</strong><p>Raw source tetap disimpan. Tidak ada perubahan sebelum preview disetujui.</p><input id="csv-file" type="file" accept=".csv,.tsv,text/csv" aria-label="Pilih file CSV"></div><div id="import-options"></div><div id="import-preview"></div>`);}
 if(settingsTab==='history'){body=panel('Batch impor tersimpan','Rollback mengganti dataset aktif, bukan menghapus arsip atau mengubah saldo snapshot.',table(['Berkas / waktu','Jumlah','Status','Aksi'],state.batches.map(b=>`<tr><td>${esc(b.filename)}<small>${new Date(b.at).toLocaleString('id-ID')}</small></td><td class="numeric">${b.counts?.after||'—'}</td><td class="numeric">${b.id===state.active?'Aktif':'Arsip'}</td><td class="numeric">${b.id!==state.active?`<button data-rollback="${esc(b.id)}">Tinjau rollback</button>`:'—'}</td></tr>`).join('')),btn('Unduh backup privat','backup'))+panel('Versi pengaturan','Pemulihan membuat versi baru dan meninggalkan audit trail.',state.configVersions.map(x=>row('Versi '+x.version,new Date(x.at).toLocaleString('id-ID'),`<button data-restore="${x.version}">Pulihkan</button>`)).join(''))+panel('Audit aktivitas','Operasi aktual pada database privat.',state.audit.map(x=>row(esc(x.action),new Date(x.at).toLocaleString('id-ID'),'#'+x.id)).join(''))+panel('Snapshot history','Posisi tidak direkonstruksi dari harga terkini.',table(['Tanggal','Net Liquidity','Book net worth','Status'],state.snapshots.map(x=>`<tr><td>${fmtDate(x.asOf)}</td>${num(x.nl)}${num(x.bookWorth)}<td class="numeric">${x.closed?'Closed':'Provisional'}</td></tr>`).join('')));}
 $('#content').innerHTML=intro('Data yang dapat dipercaya.','Sumber, keputusan klasifikasi dan perubahan memiliki jejak.')+tabs+body;
 if(settingsTab==='import'&&upload)importOptions();
}
function collectConfig(){const next=structuredClone(draft);$$('[data-config]').forEach(el=>{const path=el.dataset.config.split('.'),k=path.pop();let obj=next;for(const part of path)obj=obj[part];let v=el.value;if(el.dataset.type==='json')v=JSON.parse(v);else if(el.dataset.type==='boolean')v=el.checked;else if(el.dataset.type==='number')v=Number(v);else if(el.dataset.type==='nullable')v=v===''?null:/^-?\d+(\.\d+)?$/.test(v)?Number(v):v;obj[k]=v;});return next;}
async function loadCSV(file){if(!file)return;if(file.size>15000000)throw new Error('File maksimal 15 MB.');const bytes=await file.arrayBuffer(),decoded=decodeCSV(bytes);upload={bytes,filename:file.name,...decoded};preview=null;importOptions();}
function importOptions(){const info=inspectCSV(upload.text);$('#import-options').innerHTML=`<hr><span class="step-label">02 · FORMAT & PEMETAAN</span><p>${esc(upload.filename)} · ${info.rows.length.toLocaleString('id-ID')} baris · ${esc(upload.encoding)}</p><div class="form-grid" style="margin-top:15px"><label>Mode<select id="import-mode"><option value="replace">Ganti ekspor lengkap (termasuk koreksi lama)</option><option value="incremental">Tambahkan transaksi baru</option></select></label><label>Tanggal<select id="date-order"><option>DMY</option><option>MDY</option><option>YMD</option></select></label><label>Pemisah<select id="delimiter">${[[',','Koma'],[';','Titik koma'],['\t','Tab'],['|','Pipe']].map(([v,l])=>`<option value="${esc(v)}" ${v===info.delimiter?'selected':''}>${l}</option>`).join('')}</select></label><label>Encoding<select id="encoding">${['utf-8','utf-16le','utf-16be','windows-1252'].map(v=>`<option ${v===upload.encoding?'selected':''}>${v}</option>`).join('')}</select></label><label>Format nominal<select id="number-locale"><option value="auto">Otomatis</option><option value="id">Indonesia · 1.000,00</option><option value="en">English · 1,000.00</option></select></label><label class="checkbox"><input id="preserve-support" type="checkbox" checked>Pertahankan histori nonlaporan bila ekspor hanya laporan</label>${FIELDS.map(f=>`<label>${f}<select data-map="${f}"><option value="">Tidak tersedia</option>${info.headers.map(h=>`<option value="${esc(h)}" ${h===info.mapping[f]?'selected':''}>${esc(h)}</option>`).join('')}</select></label>`).join('')}</div><div class="toolbar" style="margin-top:20px">${btn('Preview sebelum menyimpan','import-preview','primary')}</div>`;}
function importInput(){return {revision:state.revision,filename:upload.filename,raw:upload.text,options:{mode:$('#import-mode').value,dateOrder:$('#date-order').value,delimiter:$('#delimiter').value,numberLocale:$('#number-locale').value,preserveExcluded:$('#preserve-support').checked,mapping:Object.fromEntries($$('[data-map]').map(x=>[x.dataset.map,x.value])),encoding:upload.encoding}};}
function render(){if(!state||!c||!range)return;charts.forEach(x=>x.destroy());charts=[];$('#page-title').textContent=nav.find(x=>x[0]===view)?.[3]||'Finance';$$('[data-go]').forEach(x=>x.classList.toggle('active',x.dataset.go===view));$('#status-line').innerHTML=`<span class="live-dot"></span>PRIVATE · posisi ${fmtDate(c.asOf)} <span>·</span> laporan ${fmtDate(range.start)} – ${fmtDate(range.end)}<span class="spacer"></span><button data-go="settings">Data health ↗</button>`;$('#data-footer').textContent=`${state.transactions.length.toLocaleString('id-ID')} catatan · posisi provisional`;({overview,cashflow,transactions,assets,goals,investments,roadmap,insights,settings}[view]||overview)();}
function go(v){if(!nav.some(n=>n[0]===v))return;view=v;page=0;$('#dialog').close();history.replaceState(null,'','#'+v);render();window.scrollTo({top:0});}
function syncFilters(){$('#start').value=range.start;$('#end').value=range.end;$('#group').value=range.group;$('#account').value=range.account;$('#preset').value='custom';}
function setPreset(v){const end=state.coverage.end;if(v==='ytd'){range.start=end.slice(0,4)+'-01-01';range.end=end;}else if(v==='month'){range.start=end.slice(0,7)+'-01';range.end=end;}else if(v==='last'){range.start=E.shiftMonth(end.slice(0,7)+'-01',-1);range.end=E.addDays(end.slice(0,7)+'-01',-1);}else if(v==='all'){range.start=state.coverage.start;range.end=end;}$('#start').value=range.start;$('#end').value=range.end;}
async function action(name){
 if(name==='ma-toggle'){showMA=!showMA;render();}if(name==='compare-toggle'){showPrevious=!showPrevious;render();}if(name==='real-toggle'){realRetirement=!realRetirement;render();}if(name==='prev-page'){page--;transactions();}if(name==='next-page'){page++;transactions();}if(name==='clear-category'){categoryFilter='';transactions();}if(name==='export-tx')exportRows(transactionItems());
 if(name==='car-calculate'||name==='car-save'){carDraft=structuredClone(c.car);$$('[data-car]').forEach(x=>carDraft[x.dataset.car]=x.dataset.car==='financing'?x.value==='true':x.type==='number'?Number(x.value):x.value);if(name==='car-save'){await saveConfig({...c,car:carDraft});}render();}
 if(name==='config-preview'){draft=collectConfig();const keys=Object.keys(draft).filter(k=>JSON.stringify(c[k])!==JSON.stringify(draft[k]));if(!keys.length){toast('Tidak ada perubahan.');return;}modal('Tinjau pengaturan',note('Bagian berubah: '+keys.map(k=>esc(settingLabels[k]||k)).join(', '))+`<p class="subtle">Transaksi asli tidak diubah. Versi pengaturan sebelumnya dapat dipulihkan.</p><div style="margin-top:20px">${btn('Simpan versi baru','config-save','primary')}</div>`);}
 if(name==='config-save'){await saveConfig(draft);draft=null;$('#dialog').close();render();}
 if(name==='import-preview'){const input=importInput();preview={input,result:await api('preview',input)};const p=preview.result;$('#import-preview').innerHTML=panel('03 · Tinjau dampak impor','Belum ada transaksi yang ditulis.',`<div class="grid four">${metric('Baru',String(p.counts.added))}${metric('Identik',String(p.counts.duplicates))}${metric('Dihapus / diganti',String(p.counts.removed))}${metric('Error',String(p.counts.errors),'',p.counts.errors?'negative':'')}</div>${note(`${p.counts.before} → ${p.counts.after} catatan. ${p.retainedSupport} histori nonlaporan dipertahankan. ${p.correctionCandidates?.length||0} kandidat koreksi nominal. IDs ekspor tidak dianggap permanen.`)}${p.truncated?note('Rentang ekspor memotong histori. Penggantian akan ditolak.','warning'):''}${p.errors.map(x=>`<p class="form-error">Baris ${x.row}: ${esc(x.error)}</p>`).join('')}${table(['Tanggal','Kategori','Nominal'],p.records.map(t=>`<tr><td>${t.date}</td><td>${esc(t.category)}</td>${num(t.amount)}</tr>`).join(''))}<div style="margin-top:20px">${btn(p.noChange?'Konfirmasi · tidak ada perubahan':'Simpan hasil impor','import-save','primary')}</div>`);}
 if(name==='import-save'){if(!preview)throw new Error('Buat preview terlebih dahulu.');if(JSON.stringify(importInput())!==JSON.stringify(preview.input))throw new Error('Opsi berubah. Buat preview baru.');const result=await api('import',{...preview.input,previewToken:preview.result.previewToken});await reload();preview=null;upload=null;toast(result.noChange?'Impor identik; tidak ada transaksi tambahan.':'Impor tersimpan. Tinjau rekonsiliasi posisi.');settingsTab='health';render();}
 if(name==='backup'){const data=await api('backup');download('finance-private-backup.json',JSON.stringify(data),'application/json');toast('Backup privat diunduh. Simpan dengan aman.');}
 if(name==='snapshot')modal('Catat posisi keuangan',`<p class="subtle">Tanggal posisi ${fmtDate(c.asOf)}. Saldo mengikuti pengaturan saat ini.</p><label style="margin:15px 0">Sumber posisi<input id="snapshot-source" value="${esc(c.source)}"></label><label class="checkbox"><input id="snapshot-close" type="checkbox">Ajukan tutup bulan (server memeriksa rekonsiliasi)</label><div style="margin-top:20px">${btn('Simpan snapshot','snapshot-save','primary')}</div>`);
 if(name==='snapshot-save'){await api('snapshot',{revision:state.revision,source:$('#snapshot-source').value,closed:$('#snapshot-close').checked,reconciled:$('#snapshot-close').checked});await reload();$('#dialog').close();render();toast('Snapshot tersimpan.');}
}
document.addEventListener('click',async event=>{const target=event.target.closest('button,a[data-go],tr[data-tx]');if(!target)return;try{
 if(target.dataset.go){go(target.dataset.go);return;}if(target.dataset.tx){showTransaction(target.dataset.tx);return;}if(target.dataset.edit){settingsTab='config';draft=null;go('settings');const d=$(`[data-section="${target.dataset.edit}"]`);if(d){d.open=true;d.scrollIntoView({block:'start'});}return;}
 if(target.dataset.settings){settingsTab=target.dataset.settings;draft=null;render();return;}
 if(target.dataset.action){target.disabled=true;try{await action(target.dataset.action);}finally{target.disabled=false;}}
 if(target.dataset.saveTx){const config=structuredClone(c),uid=target.dataset.saveTx;config.overrides[uid]={kind:$('#tx-kind').value,originalUid:$('#tx-original').value||null};await saveConfig(config);$('#dialog').close();render();}
 if(target.dataset.rollback)modal('Tinjau rollback',note('Dataset aktif kembali ke batch pilihan. Seluruh versi tetap tersimpan; saldo screenshot dan pengaturan tidak berubah.')+`<button class="button primary" data-confirm-rollback="${target.dataset.rollback}">Pulihkan dataset ini</button>`);
 if(target.dataset.confirmRollback){await api('rollback',{revision:state.revision,batchId:target.dataset.confirmRollback});await reload();$('#dialog').close();render();}
 if(target.dataset.restore)modal('Pulihkan pengaturan',note('Buat versi baru menggunakan pengaturan versi '+esc(target.dataset.restore)+'?')+`<button class="button primary" data-confirm-restore="${target.dataset.restore}">Pulihkan versi ini</button>`);
 if(target.dataset.confirmRestore){await api('restore-config',{revision:state.revision,version:Number(target.dataset.confirmRestore)});await reload();$('#dialog').close();render();}
 }catch(error){toast(error.message);}});
document.addEventListener('change',async event=>{if(!state||!range)return;const x=event.target;try{if(x.id==='preset'){setPreset(x.value);render();}if(x.id==='kind-filter'){kindFilter=x.value;page=0;transactions();}if(x.id==='bar-mode'){barMode=x.value;render();}if(x.id==='basis'){basis=x.value;render();}if(x.id==='family'){family=x.value==='family';render();}if(x.id==='csv-file')await loadCSV(x.files[0]);if(x.id==='encoding'){Object.assign(upload,decodeCSV(upload.bytes,x.value));preview=null;importOptions();}if(x.id==='delimiter'){const info=inspectCSV(upload.text,x.value);$$('[data-map]').forEach(el=>{el.innerHTML='<option value="">Tidak tersedia</option>'+info.headers.map(h=>`<option ${h===info.mapping[el.dataset.map]?'selected':''} value="${esc(h)}">${esc(h)}</option>`).join('');});preview=null;}}catch(e){toast(e.message);}});
let searchTimer;document.addEventListener('input',e=>{if(e.target.id==='search'){search=e.target.value;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{const cursor=e.target.selectionStart;page=0;transactions();$('#search').focus();$('#search').setSelectionRange(cursor,cursor);},220);}});
document.addEventListener('dragover',e=>{if(e.target.closest('#dropzone')){e.preventDefault();$('#dropzone').classList.add('drag');}});document.addEventListener('drop',async e=>{if(e.target.closest('#dropzone')){e.preventDefault();$('#dropzone').classList.remove('drag');try{await loadCSV(e.dataTransfer.files[0]);}catch(x){toast(x.message);}}});
$('#dialog-close').onclick=()=>$('#dialog').close();$('#apply-filter').onclick=()=>{if(!state||!range)return;const start=$('#start').value,end=$('#end').value;if(!start||!end||start>end||start<state.coverage.start||end>state.coverage.end){toast('Pilih rentang dalam histori '+state.coverage.start+' sampai '+state.coverage.end);return;}range={start,end,group:$('#group').value,account:$('#account').value};page=0;render();};
$('#exact-toggle').onclick=()=>{exact=!exact;try{localStorage.setItem('finance-exact',String(exact));}catch{}$('#exact-toggle').setAttribute('aria-pressed',String(exact));$('#exact-toggle').textContent=exact?'Rp 1.000':'Rp ≈';render();};
$('#report-export').onclick=()=>{if(state&&range)exportRows(periodRows());};$('#logout').onclick=async()=>{try{await api('logout',{});location.assign('/finance-login');}catch(e){toast(e.message);}};
document.addEventListener('finance-theme-change',()=>{if(state)render();});
async function start(){try{await reload();range={start:state.coverage.end.slice(0,4)+'-01-01',end:state.coverage.end,group:'monthly',account:''};$('#account').innerHTML='<option value="">Semua rekening</option>'+c.accounts.map(a=>`<option value="${esc(a.name)}">${esc(a.name)}</option>`).join('');setPreset('ytd');$('#desktop-nav').innerHTML=nav.map(([k,i,l])=>`<button data-go="${k}"><span>${i}</span>${l}</button>`).join('');$('#mobile-nav').innerHTML=nav.slice(0,3).map(([k,i,l])=>`<button data-go="${k}"><span>${i}</span>${l}</button>`).join('')+'<button id="more"><span>•••</span>Lainnya</button>';$('#more').onclick=()=>modal('Jelajahi keuanganmu',nav.slice(3).map(([k,i,l])=>`<div class="row"><button class="text-button" data-go="${k}">${i} &nbsp; ${l}</button></div>`).join(''));view=nav.some(x=>x[0]===location.hash.slice(1))?location.hash.slice(1):'overview';render();
 const results=await Promise.allSettled([fetch('/data/valuation-bands.json').then(r=>{if(!r.ok)throw Error();return r.json();}),api('bitcoin')]);if(results[0].status==='fulfilled'){valuation=results[0].value;market.holdings=valuation.holdings;}if(results[1].status==='fulfilled')market={...market,...results[1].value};if(!['settings','transactions'].includes(view))render();
 }catch(error){$('#content').innerHTML=panel('Dashboard belum dapat dimuat',esc(error.message),'<button class="button primary" id="retry">Coba lagi</button>');$('#retry').onclick=start;}}
start();
